    pub fn list_ai_usage(&self,limit:i64)->Result<Vec<serde_json::Value>,RepositoryError>{let mut statement=self.connection.prepare("SELECT r.id,r.provider_config_id,pc.label,r.model_id,r.task,r.status,r.created_at,r.completed_at,r.response_metadata_json,c.estimated_input_tokens FROM ai_runs r LEFT JOIN provider_configs pc ON pc.id=r.provider_config_id LEFT JOIN context_packages c ON c.id=r.context_package_id ORDER BY r.created_at DESC LIMIT ?1")?;let rows=statement.query_map([limit.clamp(1,200)],|row|{let metadata:String=row.get::<_,Option<String>>(8)?.unwrap_or_else(||"{}".into());let usage:serde_json::Value=serde_json::from_str(&metadata).unwrap_or_default();Ok(serde_json::json!({"id":row.get::<_,String>(0)?,"providerId":row.get::<_,String>(1)?,"providerLabel":row.get::<_,Option<String>>(2)?,"model":row.get::<_,String>(3)?,"task":row.get::<_,String>(4)?,"status":row.get::<_,String>(5)?,"createdAt":row.get::<_,String>(6)?,"completedAt":row.get::<_,Option<String>>(7)?,"estimatedInputTokens":row.get::<_,i64>(9)?,"actualInputTokens":usage.get("inputTokens").and_then(|value|value.as_i64()),"actualOutputTokens":usage.get("outputTokens").and_then(|value|value.as_i64()),"usageSource":usage.get("source").and_then(|value|value.as_str())}))})?.collect::<Result<Vec<_>,_>>()?;Ok(rows)}

    pub fn complete_editor_run(&self, prepared: PreparedEditorRun, output: crate::providers::EditorModelOutput, provider_label: &str, model: &str) -> Result<EditorRunDto, RepositoryError> {
        let proposal_id = Uuid::new_v4().to_string();
        let change_set_id = Uuid::new_v4().to_string();
        let now = Utc::now().to_rfc3339();
        let project_id: String = self.connection.query_row("SELECT project_id FROM manuscript_nodes WHERE id=?1", [&prepared.document_id], |row| row.get(0))?;
        let transaction = self.connection.unchecked_transaction()?;
        transaction.execute("UPDATE ai_runs SET status='succeeded',response_metadata_json='{}',completed_at=?1 WHERE id=?2", params![now, prepared.run_id])?;
        transaction.execute("INSERT INTO change_sets(id,ai_run_id,project_id,title,status,created_at) VALUES(?1,?2,?3,'AI Editor proposal','pending',?4)", params![change_set_id, prepared.run_id, project_id, now])?;
        transaction.execute("INSERT INTO change_proposals(id,change_set_id,document_id,base_revision,base_content_hash,range_from,range_to,before_text,after_text,issue,rationale,evidence_json,strategies_json,context_package_id,created_at) VALUES(?1,?2,?3,?4,?5,0,?6,?7,?8,?9,?10,?11,?12,?13,?14)", params![proposal_id, change_set_id, prepared.document_id, prepared.base_revision, prepared.base_hash, prepared.selected_text.chars().count() as i64, prepared.selected_text, output.replacement, output.issue, output.rationale, serde_json::to_string(&output.evidence)?, serde_json::to_string(&output.strategies)?, prepared.context_id, now])?;
        transaction.commit()?;
        Ok(EditorRunDto { proposal: EditorProposalDto { id: proposal_id, run_id: prepared.run_id, document_id: prepared.document_id, base_revision: prepared.base_revision, base_content_hash: prepared.base_hash, before: prepared.selected_text, after: output.replacement, issue: output.issue, rationale: output.rationale, evidence: output.evidence, strategies: output.strategies, context_package_id: prepared.context_id, decision: "pending".into(), editing_mode:"tracked-rewrite".into(), created_at: now }, context_items: prepared.context_items, estimated_input_tokens: prepared.estimated_tokens, actual_input_tokens:None,actual_output_tokens:None,provider_label: provider_label.into(), model: model.into() })
    }

    pub fn record_proposal_lineage(&self,proposal_id:&str,parent_proposal_id:Option<&str>,instruction:Option<&str>,editing_mode:&str)->Result<(),RepositoryError>{
        if !matches!(editing_mode,"suggest-only"|"tracked-rewrite"|"direct-apply"){return Err(RepositoryError::InvalidProject("Invalid proposal editing mode".into()))}
        if let Some(parent)=parent_proposal_id{let compatible:bool=self.connection.query_row("SELECT EXISTS(SELECT 1 FROM change_proposals child JOIN change_proposals parent ON parent.id=?1 WHERE child.id=?2 AND child.document_id=parent.document_id)",params![parent,proposal_id],|row|row.get(0))?;if !compatible{return Err(RepositoryError::InvalidProject("A regenerated proposal must descend from a proposal for the same document".into()))}}
        self.connection.execute("UPDATE change_proposals SET parent_proposal_id=?1,regeneration_instruction=?2,editing_mode=?3 WHERE id=?4",params![parent_proposal_id,instruction,editing_mode,proposal_id])?;Ok(())
    }

    pub fn accept_editor_proposal(&self, proposal_id: &str, replacement: Option<&str>) -> Result<AcceptedProposalDto, RepositoryError> {
        let (document_id, base_revision, base_hash, before, after): (String, i64, String, String, String) = self.connection.query_row("SELECT document_id,base_revision,base_content_hash,before_text,after_text FROM change_proposals WHERE id=?1", [proposal_id], |row| Ok((row.get(0)?,row.get(1)?,row.get(2)?,row.get(3)?,row.get(4)?))).optional()?.ok_or_else(|| RepositoryError::InvalidProject("Proposal was not found".into()))?;
        let already_decided: bool = self.connection.query_row("SELECT EXISTS(SELECT 1 FROM proposal_decisions WHERE proposal_id=?1)", [proposal_id], |row| row.get(0))?;
        if already_decided { return Err(RepositoryError::InvalidProject("This proposal has already been decided".into())); }
        let (revision, path, hash): (i64, String, String) = self.connection.query_row("SELECT revision,content_path,content_hash FROM manuscript_nodes WHERE id=?1", [&document_id], |row| Ok((row.get(0)?,row.get(1)?,row.get(2)?)))?;
        if revision != base_revision || hash != base_hash { return Err(RepositoryError::StaleRevision { expected: base_revision, actual: revision }); }
        let current = fs::read_to_string(self.root.join(path))?;
        if current.matches(&before).count() != 1 { return Err(RepositoryError::InvalidProject("The affected text is no longer uniquely identifiable".into())); }
        let accepted = replacement.unwrap_or(&after);
        if accepted.trim().is_empty() && !after.trim().is_empty() { return Err(RepositoryError::InvalidProject("The reviewed replacement cannot be empty".into())); }
        let updated = current.replacen(&before, accepted, 1);
        let next = self.save_document_with_source(&document_id, &updated, revision, "ai-accepted")?;
        let note=if accepted==after{"Applied complete proposal through revision precondition"}else{"Applied author-reviewed partial or edited proposal through revision precondition"};
        self.connection.execute("INSERT INTO proposal_decisions(id,proposal_id,decision,decided_at,note) VALUES(?1,?2,'accepted',?3,?4)", params![Uuid::new_v4().to_string(), proposal_id, Utc::now().to_rfc3339(),note])?;
        Ok(AcceptedProposalDto { content: updated, revision: next, proposal_id: proposal_id.into() })
    }

    pub fn decide_editor_proposal(&self, proposal_id: &str, decision: &str) -> Result<(), RepositoryError> {
        if !matches!(decision, "rejected" | "deferred") { return Err(RepositoryError::InvalidProject("Decision must be rejected or deferred".into())); }
        let exists: bool = self.connection.query_row("SELECT EXISTS(SELECT 1 FROM change_proposals WHERE id=?1)", [proposal_id], |row| row.get(0))?;
        if !exists { return Err(RepositoryError::InvalidProject("Proposal was not found".into())); }
        let decided: bool = self.connection.query_row("SELECT EXISTS(SELECT 1 FROM proposal_decisions WHERE proposal_id=?1)", [proposal_id], |row| row.get(0))?;
        if decided { return Err(RepositoryError::InvalidProject("This proposal has already been decided".into())); }
        self.connection.execute("INSERT INTO proposal_decisions(id,proposal_id,decision,decided_at) VALUES(?1,?2,?3,?4)", params![Uuid::new_v4().to_string(), proposal_id, decision, Utc::now().to_rfc3339()])?;
        Ok(())
    }

