    pub fn save_character_state(&self, mut state: serde_json::Value) -> Result<serde_json::Value, RepositoryError> {
        let object = state.as_object_mut().ok_or_else(|| RepositoryError::InvalidProject("Character state must be an object".into()))?;
        let id = object.get("id").and_then(|value| value.as_str()).filter(|value| !value.is_empty()).map(str::to_owned).unwrap_or_else(|| Uuid::new_v4().to_string());
        object.insert("id".into(), id.clone().into());
        let character_id = object.get("characterId").and_then(|value| value.as_str()).ok_or_else(|| RepositoryError::InvalidProject("Character state requires a character".into()))?.to_owned();
        let from = object.get("effectiveFromNodeId").and_then(|value| value.as_str()).ok_or_else(|| RepositoryError::InvalidProject("Character state requires a starting scene".into()))?.to_owned();
        let to = object.get("effectiveToNodeId").and_then(|value| value.as_str()).filter(|value| !value.is_empty()).map(str::to_owned);
        let source = object.get("source").and_then(|value| value.as_str()).unwrap_or("manual").to_owned();
        if !matches!(source.as_str(), "manual" | "accepted-extraction" | "revision") { return Err(RepositoryError::InvalidProject("Invalid character-state source".into())); }
        let confidence = object.get("confidence").and_then(|value| value.as_f64());
        let character_exists: bool = self.connection.query_row("SELECT EXISTS(SELECT 1 FROM characters WHERE id=?1 AND deleted_at IS NULL)", [&character_id], |row| row.get(0))?;
        let from_exists: bool = self.connection.query_row("SELECT EXISTS(SELECT 1 FROM manuscript_nodes WHERE id=?1 AND deleted_at IS NULL)", [&from], |row| row.get(0))?;
        if !character_exists || !from_exists { return Err(RepositoryError::InvalidProject("Character or story position does not exist".into())); }
        let aggregate = serde_json::to_string(&state)?;
        self.connection.execute("INSERT INTO character_states(id,character_id,effective_from_node_id,effective_to_node_id,aggregate_json,source,confidence,created_at) VALUES(?1,?2,?3,?4,?5,?6,?7,?8) ON CONFLICT(id) DO UPDATE SET effective_from_node_id=excluded.effective_from_node_id,effective_to_node_id=excluded.effective_to_node_id,aggregate_json=excluded.aggregate_json,source=excluded.source,confidence=excluded.confidence", params![id, character_id, from, to, aggregate, source, confidence, Utc::now().to_rfc3339()])?;
        Ok(state)
    }

